{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "The S3 bucket lacks an aws_s3_bucket_public_access_block resource, leaving it potentially exposed to public access if other configurations or defaults allow it."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "Ensure that S3 buckets are encrypted with KMS by default",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "Server-side encryption is not explicitly configured. While AWS may apply default encryption, best practice for CloudTrail logs requires explicit SSE-KMS configuration to ensure data at rest is protected with customer-managed keys."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "Versioning is not enabled on the bucket. For audit logs like CloudTrail, versioning provides protection against accidental deletion or overwriting of log files."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "S3 server access logging is not configured. This prevents tracking of requests made to the bucket, which is critical for security auditing and incident response."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"cloudtrail_logs\" {\n  bucket = \"fleet-management-gps-tracking-system-cloudtrail-${random_string.bucket_suffix.result}\"\n}\n\nresource \"aws_s3_bucket_public_access_block\" \"cloudtrail_logs\" {\n  bucket                  = aws_s3_bucket.cloudtrail_logs.id\n  block_public_acls       = true\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n}\n\nresource \"aws_s3_bucket_server_side_encryption_configuration\" \"cloudtrail_logs\" {\n  bucket = aws_s3_bucket.cloudtrail_logs.id\n\n  rule {\n    apply_server_side_encryption_by_default {\n      sse_algorithm = \"aws:kms\"\n    }\n  }\n}\n\nresource \"aws_s3_bucket_versioning\" \"cloudtrail_logs\" {\n  bucket = aws_s3_bucket.cloudtrail_logs.id\n  versioning_configuration {\n    status = \"Enabled\"\n  }\n}\n\nresource \"aws_s3_bucket_logging\" \"cloudtrail_logs\" {\n  bucket        = aws_s3_bucket.cloudtrail_logs.id\n  target_bucket = aws_s3_bucket.cloudtrail_logs.id # In production, this should be a separate dedicated logging bucket\n  target_prefix = \"log/\"\n}",
  "fix_summary": "Added resources to enforce public access blocking, enable KMS encryption, enable versioning, and configure server access logging for the CloudTrail S3 bucket."
}
